S=[]
S.append(TITLE('TIN HỌC · WEB 5B','FLEXBOX, VỊ TRÍ<br>VÀ GIAO DIỆN ĐÁP ỨNG','display: flex, trục chính – trục phụ, justify-content, align-items, flex-direction; position: static, relative, absolute, fixed, sticky; đơn vị tương đối; @media.',['flex','position','rem','@media']))
S.append(goals(c,B,['Dùng <b>Flexbox</b> xếp phần tử: <b>justify-content</b> (trục chính), <b>align-items</b> (trục phụ).','Phân biệt các giá trị <b>position</b> và mốc định vị của từng loại.','Dùng đơn vị <b>em, rem, %, vw</b> cho trang co giãn.','Viết <b>@media</b> để trang đáp ứng nhiều cỡ màn hình.'],['Flexbox','Position','Đơn vị','@media']))
S.append(S2(c,B+' · 1','Flexbox: bật bố cục linh hoạt',card('display: flex',P('Đặt <b>display: flex</b> cho <b>phần tử cha</b> (flex container); các <b>con trực tiếp</b> thành flex item xếp <b>theo hàng ngang</b>.','Hai trục: <b>trục chính</b> (main axis, mặc định ngang) và <b>trục phụ</b> (cross axis, vuông góc).')),CODE('.f { display: flex; }',24)+FX('display:flex',130)+KEY('Không có flex: ba hộp xếp dọc (block). Có <b>display:flex</b>: xếp ngang.')))
