S.append(S2(c,B+' · 1','align-items: căn theo TRỤC PHỤ',card('Các giá trị',P('<b>stretch</b> (mặc định), <b>flex-start</b>, <b>center</b>, <b>flex-end</b>.','Với hàng ngang, trục phụ là <b>chiều dọc</b>: <b>align-items: center</b> căn giữa theo chiều cao.')),FX('display:flex;align-items:center',130)+FX('display:flex;justify-content:center;align-items:center',130)+KEY('<b>align-items</b> căn theo <b>trục phụ</b>. Căn giữa hoàn hảo: <b>cả hai</b> thuộc tính.')))
S.append(S2(c,B+' · 1','flex-direction và flex-wrap',card('Đổi hướng trục chính',P('<b>row</b> (mặc định): trục chính ngang. <b>column</b>: trục chính <b>dọc</b>.','Khi <b>column</b>, hai trục <b>đổi vai</b>: justify-content căn dọc, align-items căn ngang.','<b>flex-wrap: wrap</b>: cho xuống dòng khi hết chỗ; <b>gap</b>: khoảng cách giữa các item.')),FX('display:flex;flex-direction:column;gap:6px;height:150px',170)+KEY('Với <b>flex-direction: column</b>, trục chính trở thành <b>chiều dọc</b>.')))
S.append(S2(c,B+' · 1','Menu ngang bằng Flexbox',card('Ứng dụng điển hình',P('Cho <b>ul</b> thành flex container, bỏ chấm và dàn đều các mục.')),CODE('ul {\n  display: flex;\n  list-style: none;\n  gap: 16px;\n}',22)+BROWSER('<ul><li><a href="#">Trang chủ</a></li><li><a href="#">Giới thiệu</a></li><li><a href="#">Liên hệ</a></li></ul>','ul{display:flex;list-style:none;gap:16px;background:#BBDEFB;padding:10px;margin:0}a{text-decoration:none;font-weight:bold;color:#0D47A1}',h=70)))
S.append(TB(c,B+' · 2','Thuộc tính position',['Giá trị','Mốc định vị','Trong luồng?'],[['<code>static</code>','mặc định, không định vị','có'],['<code>relative</code>','lệch so với <b>vị trí gốc của chính nó</b>','có (chỗ cũ vẫn giữ)'],['<code>absolute</code>','so với <b>tổ tiên gần nhất đã được định vị</b> (không thì so với trang)','<b>không</b>'],['<code>fixed</code>','so với <b>khung nhìn</b> (viewport), đứng yên khi cuộn','<b>không</b>'],['<code>sticky</code>','dính khi cuộn tới ngưỡng, rồi cố định','có']],note=KEY('Thường đặt <b>position: relative</b> cho phần tử cha để con <b>absolute</b> lấy cha làm mốc.')))
S.append(S2(c,B+' · 2','absolute: mốc là tổ tiên đã định vị',card('Ví dụ góc hộp',P('Cha có <b>position: relative</b>; con <b>absolute</b> với <b>top, right</b> bám góc trên phải của cha.','Nếu cha <b>không</b> định vị, con lấy mốc xa hơn (thường là trang).')),CODE('.cha { position: relative; }\n.con { position: absolute;\n       top: 0; right: 0; }',21)+BROWSER('<div class="cha">Hộp cha<div class="con">Góc</div></div>','.cha{position:relative;height:90px;border:2px solid #1565C0;background:#E3F2FD;padding:6px}.con{position:absolute;top:0;right:0;background:#FFB300;padding:4px 10px;font-weight:bold}',h=130)))
S.append(S2(c,B+' · 2','fixed và sticky',card('Hai kiểu “dính”',P('<b>fixed</b>: mốc là <b>khung nhìn</b>; ra khỏi luồng; đứng yên khi cuộn (thanh menu, nút lên đầu trang).','<b>sticky</b>: bình thường như relative, tới ngưỡng (<code>top:0</code>) thì <b>dính</b> lại.')),CODE('.menu {\n  position: fixed;\n  top: 0; left: 0; width: 100%;\n}\nth { position: sticky; top: 0; }',21)+KEY('Muốn thanh luôn ở đầu màn hình khi cuộn: <b>position: fixed</b>.')))
S.append(S2(c,B+' · 3','Đơn vị tương đối cho giao diện co giãn',card('em, rem, %, vw',P('<b>em</b>: theo cỡ chữ của phần tử (hoặc cha khi dùng cho font-size).','<b>rem</b>: theo cỡ chữ <b>gốc</b> (html) → ổn định hơn em.','<b>%</b>: theo kích thước phần tử cha. <b>vw/vh</b>: % bề rộng/cao khung nhìn.')),T(tr('Đơn vị','Cơ sở tính',h=True)+tr('px','cố định')+tr('em','cỡ chữ phần tử')+tr('rem','cỡ chữ của html')+tr('%','phần tử cha')+tr('vw','1% bề rộng cửa sổ'))+KEY('Cỡ chữ html 16px: <b>2rem = 32px</b>; chữ 20px: <b>1.5em = 30px</b>.')))
S.append(S2(c,B+' · 4','@media: giao diện đáp ứng',card('Quy tắc theo cỡ màn hình',P('<b>@media (max-width: 600px) { … }</b>: các quy tắc bên trong chỉ áp dụng khi <b>bề rộng khung nhìn ≤ 600px</b> (điện thoại).','Cần thẻ: <code>&lt;meta name="viewport" content="width=device-width, initial-scale=1"&gt;</code>.')),CODE('.f { display: flex; }\n@media (max-width: 600px) {\n  .f { flex-direction: column; }\n}',21)+KEY('<b>@media (max-width: 600px)</b> có tác dụng khi màn hình <b>hẹp từ 600px trở xuống</b>.')))
