S.append(SELF(c,B+' · 5','Tự kiểm tra: absolute','Con có position:absolute định vị tương đối theo phần tử nào?','.cha { position: relative; }\n.con { position: absolute;\n       top:0; right:0; }',P('Theo <b>tổ tiên gần nhất đã được định vị</b> (relative, absolute, fixed, sticky); không có thì theo trang.','Vì vậy hay đặt <b>relative</b> cho cha.'),22))
S.append(SELF(c,B+' · 5','Tự kiểm tra (HSG): đúng hay sai?','(a) fixed lấy khung nhìn làm mốc. (b) display:none vẫn chiếm chỗ. (c) @media (max-width:600px) áp dụng khi màn ≤ 600px. (d) rem tính theo cỡ chữ của html. (e) sticky ra khỏi luồng như absolute.','',P('(a) <b>Đúng</b>.','(b) <b>Sai</b>: none loại hẳn khỏi bố cục.','(c) <b>Đúng</b>.','(d) <b>Đúng</b>.','(e) <b>Sai</b>: sticky <b>vẫn nằm trong luồng</b>.'),20))
